// Applies Mike's changes to the generated iOS project (ios/ is regenerated by
// `npx cap add ios` and not committed; README.md, "Native shell hardening").
// Safe to run again: each change checks whether it is already there.
//
//   - Info.plist: the mike:// URL scheme and the permission prompts for
//     dictation (microphone; speech recognition, asked only on iOS before 26)
//     and the scanner (camera, photos), and audio in the background for
//     read-aloud.
//   - SceneDelegate: a native cover over the window whenever the app leaves
//     the foreground, so the app switcher's snapshot never shows matter
//     content (CSS alone can lose that race). A personal build may show the
//     real snapshot instead: MIKE_APP_SWITCHER_PREVIEW=1 at configure time
//     sets Info.plist's MikeAppSwitcherPreview, which the cover checks. Firm
//     builds leave it unset.
//   - AppDelegate: the app's Documents and Library excluded from iCloud and
//     Finder backups, and no form bar (previous, next, Done) above the
//     keyboard: the chat composer is one field with its own send button.
//     Only that view changes.
//   - SceneDelegate: dragging the page closes the keyboard. With the form
//     bar gone this and a tap on the page (frontend
//     hooks/useBlurOnOutsideTap.ts) are how the keyboard closes.
//   - SceneDelegate: the web view bounces at the ends of the page (MIKE_BOUNCE).
//     Capacitor turns UIScrollView.bounces off; a chat thread scrolls the
//     page on a phone and should rubber-band past its end like any iOS list.
//   - SceneDelegate: on iOS 17 and later the web view ends at the keyboard's
//     top edge and WebKit is not told about the keyboard, so the page's
//     viewport is just the space above it (MIKE_KEYBOARD_LAYOUT).
//   - Deployment target 18.0 (the project, and CapApp-SPM's platform, which
//     `cap sync` re-derives from the project): the xn-ptts package that runs
//     Phonon (plugins/speech) declares iOS 18, and Swift Package Manager
//     refuses a dependency with a higher floor than the package using it.
//     Fluid Speech Mini and Phonon need iOS 18 themselves.
//   - SceneDelegate: on a Mac, no white title bar: the window controls sit
//     over the page's own colour (MIKE_MAC_TITLEBAR).
//   - AppUITests: an XCUITest target (ui-tests/AppUITests.swift) and a shared
//     "App" scheme that runs it, for scripts/ui-test-ios.sh.
import { execFileSync } from "node:child_process";
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";

const app = new URL("../ios/App/App/", import.meta.url).pathname;
const plist = `${app}Info.plist`;
const buddy = (command, quiet = false) =>
  execFileSync("/usr/libexec/PlistBuddy", ["-c", command, plist], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", quiet ? "ignore" : "inherit"],
  });
const has = (key) => {
  try {
    buddy(`Print :${key}`, true);
    return true;
  } catch {
    return false;
  }
};

const strings = {
  NSMicrophoneUsageDescription: "The microphone is used when you dictate a message or talk in voice mode.",
  NSSpeechRecognitionUsageDescription: "Mike turns your dictation into text on this iPhone. The recording never leaves it.",
  NSCameraUsageDescription: "Mike uses the camera when you scan a document.",
  NSPhotoLibraryUsageDescription: "Mike opens your photo library when you choose a picture to attach.",
  NSPhotoLibraryAddUsageDescription: "Mike saves pictures to your photo library when you ask it to.",
};
for (const [key, value] of Object.entries(strings)) {
  if (has(key)) buddy(`Set :${key} ${value}`);
  else buddy(`Add :${key} string ${value}`);
}
// Read-aloud keeps playing when the app goes to the background or the phone
// locks: one audio element in the web view, with lock-screen controls.
if (!has("UIBackgroundModes")) buddy("Add :UIBackgroundModes array");
if (!/^\s*audio$/m.test(buddy("Print :UIBackgroundModes", true))) buddy("Add :UIBackgroundModes: string audio");
if (!has("CFBundleURLTypes")) {
  buddy("Add :CFBundleURLTypes array");
  buddy("Add :CFBundleURLTypes:0 dict");
  buddy("Add :CFBundleURLTypes:0:CFBundleURLName string com.firm.mike");
  buddy("Add :CFBundleURLTypes:0:CFBundleURLSchemes array");
  buddy("Add :CFBundleURLTypes:0:CFBundleURLSchemes:0 string mike");
}

// Whether the app switcher may show the app's real snapshot (see above).
const preview = process.env.MIKE_APP_SWITCHER_PREVIEW === "1";
if (has("MikeAppSwitcherPreview")) buddy(`Set :MikeAppSwitcherPreview ${preview}`);
else buddy(`Add :MikeAppSwitcherPreview bool ${preview}`);

function patch(file, marker, apply) {
  const path = `${app}${file}`;
  const source = readFileSync(path, "utf8");
  if (source.includes(marker)) return;
  const next = apply(source);
  if (next === source) throw new Error(`could not patch ${file}`);
  writeFileSync(path, next);
}

patch("SceneDelegate.swift", "MIKE_PRIVACY_COVER", (source) =>
  source.replace(
    /\n}\s*$/,
    `

    // MIKE_PRIVACY_COVER: hide the window's content while the app is not in
    // the foreground, before iOS takes the app switcher's snapshot.
    private var privacyCover: UIView?

    func sceneWillResignActive(_ scene: UIScene) {
        // MIKE_APP_SWITCHER_PREVIEW: a personal build may opt out.
        if Bundle.main.object(forInfoDictionaryKey: "MikeAppSwitcherPreview") as? Bool == true { return }
        guard let window = window, privacyCover == nil else { return }
        let cover = UIVisualEffectView(effect: UIBlurEffect(style: .systemMaterial))
        cover.frame = window.bounds
        cover.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        window.addSubview(cover)
        privacyCover = cover
    }

    func sceneDidBecomeActive(_ scene: UIScene) {
        privacyCover?.removeFromSuperview()
        privacyCover = nil
    }
}
`,
  ),
);

// Projects configured before the opt-out existed have the cover without it.
patch("SceneDelegate.swift", "MIKE_APP_SWITCHER_PREVIEW", (source) =>
  source.replace(
    "        guard let window = window, privacyCover == nil else { return }",
    `        // MIKE_APP_SWITCHER_PREVIEW: a personal build may opt out.
        if Bundle.main.object(forInfoDictionaryKey: "MikeAppSwitcherPreview") as? Bool == true { return }
        guard let window = window, privacyCover == nil else { return }`,
  ),
);

patch("AppDelegate.swift", "MIKE_BACKUP_EXCLUSION", (source) =>
  source
    .replace(
      "        // Override point for customization after application launch.\n        return true",
      "        excludeAppDataFromBackup()\n        return true",
    )
    .replace(
      /\n}\s*$/,
      `

    // MIKE_BACKUP_EXCLUSION: session material and cached pages stay off
    // iCloud and Finder backups.
    private func excludeAppDataFromBackup() {
        let fm = FileManager.default
        let roots = fm.urls(for: .documentDirectory, in: .userDomainMask)
            + fm.urls(for: .libraryDirectory, in: .userDomainMask)
        for root in roots {
            var url = root
            var values = URLResourceValues()
            values.isExcludedFromBackup = true
            try? url.setResourceValues(values)
        }
    }
}
`,
    ),
);

patch("AppDelegate.swift", "MIKE_NO_FORM_ACCESSORY_BAR", (source) =>
  source
    .replace(
      "        excludeAppDataFromBackup()\n        return true",
      "        excludeAppDataFromBackup()\n        hideFormAccessoryBar()\n        return true",
    )
    .replace(
      /\n}\s*$/,
      `

    // MIKE_NO_FORM_ACCESSORY_BAR: WebKit's text input view offers no
    // accessory view, so the keyboard comes up without the previous, next
    // and Done bar. The override is added to that class alone.
    private func hideFormAccessoryBar() {
        guard let contentView = NSClassFromString("WKContentView") else { return }
        let selector = #selector(getter: UIResponder.inputAccessoryView)
        guard let method = class_getInstanceMethod(contentView, selector) else { return }
        let noBar: @convention(block) (AnyObject) -> UIView? = { _ in nil }
        let implementation = imp_implementationWithBlock(noBar)
        let types = method_getTypeEncoding(method)
        if !class_addMethod(contentView, selector, implementation, types) {
            class_replaceMethod(contentView, selector, implementation, types)
        }
    }
}
`,
    ),
);

patch("SceneDelegate.swift", "MIKE_KEYBOARD_DISMISS", (source) =>
  source.replace("window?.rootViewController = CAPBridgeViewController()", "window?.rootViewController = MikeBridgeViewController()") +
    `
// MIKE_KEYBOARD_DISMISS: dragging the page closes the keyboard.
class MikeBridgeViewController: CAPBridgeViewController {
    override func capacitorDidLoad() {
        super.capacitorDidLoad()
        webView?.scrollView.keyboardDismissMode = .onDrag
    }
}
`,
);
// MIKE_BOUNCE: Capacitor sets scrollView.bounces = false; turn it back on.
patch("SceneDelegate.swift", "MIKE_BOUNCE", (source) =>
  source.replace(
    "        webView?.scrollView.keyboardDismissMode = .onDrag\n",
    `        webView?.scrollView.keyboardDismissMode = .onDrag
        // MIKE_BOUNCE: rubber-band past the ends of the page (vertical only).
        webView?.scrollView.bounces = true
        webView?.scrollView.alwaysBounceVertical = true
        webView?.scrollView.alwaysBounceHorizontal = false
`,
  ),
);
patch("SceneDelegate.swift", "MIKE_KEYBOARD_LAYOUT", (source) =>
  source
    .replace(
      "window?.rootViewController = MikeBridgeViewController()",
      "window?.rootViewController = MikeKeyboardLayoutController(MikeBridgeViewController())",
    )
    // Projects patched before this change let a drag pull the keyboard down
    // with the finger, which needs the page to reach under the keyboard.
    .replace(
      "// MIKE_KEYBOARD_DISMISS: dragging the page down pulls the keyboard away with\n// it, as in Messages.",
      "// MIKE_KEYBOARD_DISMISS: dragging the page closes the keyboard.",
    )
    .replace("keyboardDismissMode = .interactive", "keyboardDismissMode = .onDrag") +
    `
// MIKE_KEYBOARD_LAYOUT: the app, not WebKit, makes room for the keyboard. The
// web view ends at the keyboard's top edge and follows it, also while it is
// dragged away, and WebKit is not told about the keyboard at all. WebKit's own
// handling shrinks the page's viewport while the keyboard is up and, on iOS
// 27, can leave it short after the keyboard closes, which floats the chat
// composer above the bottom of the screen. Before iOS 17 the keyboard guide
// stops at the safe area, which would cut the edge-to-edge page short, so
// WebKit keeps handling the keyboard there.
class MikeKeyboardLayoutController: UIViewController {
    private let bridgeController: CAPBridgeViewController

    init(_ bridgeController: CAPBridgeViewController) {
        self.bridgeController = bridgeController
        super.init(nibName: nil, bundle: nil)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) is not supported")
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        addChild(bridgeController)
        let webView: UIView = bridgeController.view
        webView.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(webView)
        var bottom = webView.bottomAnchor.constraint(equalTo: view.bottomAnchor)
        if #available(iOS 17.0, *) {
            view.keyboardLayoutGuide.usesBottomSafeArea = false
            bottom = webView.bottomAnchor.constraint(equalTo: view.keyboardLayoutGuide.topAnchor)
            let center = NotificationCenter.default
            for name in [
                UIResponder.keyboardWillShowNotification, UIResponder.keyboardDidShowNotification,
                UIResponder.keyboardWillHideNotification, UIResponder.keyboardDidHideNotification,
                UIResponder.keyboardWillChangeFrameNotification, UIResponder.keyboardDidChangeFrameNotification,
            ] {
                center.removeObserver(webView, name: name, object: nil)
            }
        }
        NSLayoutConstraint.activate([
            webView.topAnchor.constraint(equalTo: view.topAnchor),
            webView.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            webView.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            bottom,
        ])
        bridgeController.didMove(toParent: self)
    }

    override var childForStatusBarStyle: UIViewController? { bridgeController }
    override var childForStatusBarHidden: UIViewController? { bridgeController }
    override var childForHomeIndicatorAutoHidden: UIViewController? { bridgeController }
    override var supportedInterfaceOrientations: UIInterfaceOrientationMask {
        bridgeController.supportedInterfaceOrientations
    }
}
`,
);
// MIKE_KEYBOARD_OVERLAP: the keyboard slides over the bottom of the page by
// a little less than the chat composer's band below its buttons (6px gap and
// 23px padding, frontend globals.css), so it covers the composer's empty
// bottom and its rounded corners, never a button, and nothing shows behind
// the keyboard's own rounded corners. Required: the web view never reaches
// past the bottom of the screen, so with the keyboard closed nothing changes;
// preferred: it ends that far below the keyboard's top edge, following it as
// it opens, closes or is dragged away.
patch("SceneDelegate.swift", "MIKE_KEYBOARD_OVERLAP", (source) =>
  source.replace(
    "            bottom = webView.bottomAnchor.constraint(equalTo: view.keyboardLayoutGuide.topAnchor)\n",
    `            // MIKE_KEYBOARD_OVERLAP: the keyboard covers the composer's empty
            // bottom band (see configure-ios.mjs).
            bottom = webView.bottomAnchor.constraint(lessThanOrEqualTo: view.bottomAnchor)
            let overlap = webView.bottomAnchor.constraint(equalTo: view.keyboardLayoutGuide.topAnchor, constant: 24)
            overlap.priority = .defaultHigh
            overlap.isActive = true
`,
  ),
);

// MIKE_KEYBOARD_EVENTS: WebKit is not told about the keyboard (above), so the
// app tells the page: a \`mikekeyboard\` event on the window with whether it is
// open, how far it overlaps the page and how long its animation runs. The
// page uses it to shade the composer under the keyboard's edge and to move
// the composer with the keyboard instead of jumping (frontend
// lib/nativeKeyboard.ts).
patch("SceneDelegate.swift", "MIKE_KEYBOARD_EVENTS", (source) =>
  source.replace(
    "        bridgeController.didMove(toParent: self)\n    }\n",
    `        bridgeController.didMove(toParent: self)
        if #available(iOS 17.0, *) {
            NotificationCenter.default.addObserver(
                self, selector: #selector(keyboardWillChangeFrame(_:)),
                name: UIResponder.keyboardWillChangeFrameNotification, object: nil)
        }
    }

    // MIKE_KEYBOARD_EVENTS: tell the page where the keyboard is going.
    @objc private func keyboardWillChangeFrame(_ note: Notification) {
        guard let info = note.userInfo,
              let end = (info[UIResponder.keyboardFrameEndUserInfoKey] as? NSValue)?.cgRectValue else { return }
        let duration = (info[UIResponder.keyboardAnimationDurationUserInfoKey] as? Double) ?? 0.25
        let frame = view.convert(end, from: nil)
        let open = frame.height > 0 && frame.minY < view.bounds.maxY - 1
        // The same overlap as MIKE_KEYBOARD_OVERLAP.
        let script = "window.dispatchEvent(new CustomEvent('mikekeyboard', { detail: { open: \\(open), overlap: \\(open ? 24 : 0), duration: \\(Int(duration * 1000)) } }))"
        bridgeController.webView?.evaluateJavaScript(script, completionHandler: nil)
    }
`,
  ),
);

// MIKE_MAC_TITLEBAR: on a Mac (the iPhone app running there), no white title
// bar above the page. The window controls sit over the app's own content
// (the unified windowing-control style, iOS 26), the page starts just below
// them, and the strip they sit on takes the page's background colour, so it
// follows the light and dark themes. iPhone and iPad are unchanged.
patch("SceneDelegate.swift", "MIKE_MAC_TITLEBAR", (source) =>
  source
    .replace(
      "    func scene(_ scene: UIScene, openURLContexts URLContexts: Set<UIOpenURLContext>) {",
      `    // MIKE_MAC_TITLEBAR: the window controls over the content on a Mac.
    @available(iOS 26.0, *)
    func preferredWindowingControlStyle(for windowScene: UIWindowScene) -> UIWindowScene.WindowingControlStyle {
        ProcessInfo.processInfo.isiOSAppOnMac ? .unified : .automatic
    }

    func scene(_ scene: UIScene, openURLContexts URLContexts: Set<UIOpenURLContext>) {`,
    )
    .replace(
      "            webView.topAnchor.constraint(equalTo: view.topAnchor),\n",
      "            macTitlebarTop(webView),\n",
    )
    .replace(
      "    override var childForStatusBarStyle: UIViewController? { bridgeController }",
      `    // MIKE_MAC_TITLEBAR: on a Mac the page starts below the window controls,
    // on a strip the page's own background colour.
    private var backgroundObservation: NSKeyValueObservation?

    private func macTitlebarTop(_ webView: UIView) -> NSLayoutConstraint {
        guard ProcessInfo.processInfo.isiOSAppOnMac, #available(iOS 26.0, *) else {
            return webView.topAnchor.constraint(equalTo: view.topAnchor)
        }
        backgroundObservation = bridgeController.webView?.observe(\\.underPageBackgroundColor, options: [.initial, .new]) { [weak self] page, _ in
            self?.view.backgroundColor = page.underPageBackgroundColor
        }
        return webView.topAnchor.constraint(equalTo: view.layoutGuide(for: .safeArea(cornerAdaptation: .vertical)).topAnchor)
    }

    override var childForStatusBarStyle: UIViewController? { bridgeController }`,
    ),
);

// MIKE_UI_TESTS: the UI-test target. Written into project.pbxproj directly
// (no Ruby gem needed) with fixed ids, so a second run finds the marker and
// changes nothing. The Swift source is copied in on every run.
const iosApp = new URL("../ios/App/", import.meta.url).pathname;
const testDir = `${iosApp}AppUITests/`;
mkdirSync(testDir, { recursive: true });
copyFileSync(new URL("../ui-tests/AppUITests.swift", import.meta.url).pathname, `${testDir}AppUITests.swift`);

const pbxPath = `${iosApp}App.xcodeproj/project.pbxproj`;
const MIN_IOS = "18.0";
{
  const source = readFileSync(pbxPath, "utf8");
  const next = source.replace(/IPHONEOS_DEPLOYMENT_TARGET = [\d.]+;/g, `IPHONEOS_DEPLOYMENT_TARGET = ${MIN_IOS};`);
  if (next !== source) writeFileSync(pbxPath, next);
  const spmPath = `${iosApp}CapApp-SPM/Package.swift`;
  if (existsSync(spmPath)) {
    const spm = readFileSync(spmPath, "utf8");
    // The string form: `.v18` needs a tools version of 6.0, and Capacitor writes 5.9.
    const spmNext = spm.replace(/platforms: \[\.iOS\([^)]*\)\]/, `platforms: [.iOS("${MIN_IOS}")]`);
    if (spmNext !== spm) writeFileSync(spmPath, spmNext);
  }
}
const pbx = readFileSync(pbxPath, "utf8");
if (!pbx.includes("MIKE_UI_TESTS")) {
  const appTarget = /(\w{24}) \/\* App \*\/ = \{\n\t*isa = PBXNativeTarget;/.exec(pbx)?.[1];
  const project = /rootObject = (\w{24})/.exec(pbx)?.[1];
  if (!appTarget || !project) throw new Error("could not find the App target in project.pbxproj");
  const id = {
    sourceRef: "A1B2C3D4E5F60718293A4B01", sourceBuild: "A1B2C3D4E5F60718293A4B02",
    product: "A1B2C3D4E5F60718293A4B03", group: "A1B2C3D4E5F60718293A4B04",
    target: "A1B2C3D4E5F60718293A4B05", sources: "A1B2C3D4E5F60718293A4B06",
    frameworks: "A1B2C3D4E5F60718293A4B07", resources: "A1B2C3D4E5F60718293A4B08",
    proxy: "A1B2C3D4E5F60718293A4B09", dependency: "A1B2C3D4E5F60718293A4B0A",
    list: "A1B2C3D4E5F60718293A4B0B", debug: "A1B2C3D4E5F60718293A4B0C", release: "A1B2C3D4E5F60718293A4B0D",
  };
  const settings = (extra) => `{
\t\t\t\tCODE_SIGN_STYLE = Automatic;
\t\t\t\tCURRENT_PROJECT_VERSION = 1;
\t\t\t\tGENERATE_INFOPLIST_FILE = YES;
\t\t\t\tIPHONEOS_DEPLOYMENT_TARGET = ${MIN_IOS};
\t\t\t\tMARKETING_VERSION = 1.0;
\t\t\t\tPRODUCT_BUNDLE_IDENTIFIER = com.firm.mike.AppUITests;
\t\t\t\tPRODUCT_NAME = "$(TARGET_NAME)";
\t\t\t\tSWIFT_VERSION = 5.0;
\t\t\t\tTARGETED_DEVICE_FAMILY = "1,2";
\t\t\t\tTEST_TARGET_NAME = App;${extra}
\t\t\t}`;
  const add = (name, text) => {
    const end = `/* End ${name} section */`;
    if (!pbxNext.includes(end)) throw new Error(`project.pbxproj has no ${name}`);
    pbxNext = pbxNext.replace(end, `${text}${end}`);
  };
  let pbxNext = pbx;
  // Sections the generated project lacks (cap add ios does not emit them).
  const section = (name, body) => `\n/* Begin ${name} section */\n${body}/* End ${name} section */\n`;
  add("PBXBuildFile", `\t\t${id.sourceBuild} /* AppUITests.swift in Sources */ = {isa = PBXBuildFile; fileRef = ${id.sourceRef} /* AppUITests.swift */; };\n`);
  add(
    "PBXFileReference",
    `\t\t${id.sourceRef} /* AppUITests.swift */ = {isa = PBXFileReference; lastKnownFileType = sourcecode.swift; path = AppUITests.swift; sourceTree = "<group>"; };\n` +
      `\t\t${id.product} /* AppUITests.xctest */ = {isa = PBXFileReference; explicitFileType = wrapper.cfbundle; includeInIndex = 0; path = AppUITests.xctest; sourceTree = BUILT_PRODUCTS_DIR; };\n`,
  );
  pbxNext = pbxNext
    .replace(/(504EC2FB1FED79650016851F = \{\n\t\t\tisa = PBXGroup;\n\t\t\tchildren = \(\n)/, `$1\t\t\t\t${id.group} /* AppUITests */,\n`)
    .replace(/(\/\* Products \*\/ = \{\n\t\t\tisa = PBXGroup;\n\t\t\tchildren = \(\n)/, `$1\t\t\t\t${id.product} /* AppUITests.xctest */,\n`);
  add(
    "PBXGroup",
    `\t\t${id.group} /* AppUITests */ = {\n\t\t\tisa = PBXGroup;\n\t\t\tchildren = (\n\t\t\t\t${id.sourceRef} /* AppUITests.swift */,\n\t\t\t);\n\t\t\tpath = AppUITests;\n\t\t\tsourceTree = "<group>";\n\t\t};\n`,
  );
  add(
    "PBXNativeTarget",
    `\t\t${id.target} /* AppUITests */ = {\n\t\t\tisa = PBXNativeTarget;\n\t\t\tbuildConfigurationList = ${id.list} /* Build configuration list for PBXNativeTarget "AppUITests" */;\n\t\t\tbuildPhases = (\n\t\t\t\t${id.sources} /* Sources */,\n\t\t\t\t${id.frameworks} /* Frameworks */,\n\t\t\t\t${id.resources} /* Resources */,\n\t\t\t);\n\t\t\tbuildRules = (\n\t\t\t);\n\t\t\tdependencies = (\n\t\t\t\t${id.dependency} /* PBXTargetDependency */,\n\t\t\t);\n\t\t\tname = AppUITests;\n\t\t\tproductName = AppUITests;\n\t\t\tproductReference = ${id.product} /* AppUITests.xctest */;\n\t\t\tproductType = "com.apple.product-type.bundle.ui-testing";\n\t\t};\n`,
  );
  pbxNext = pbxNext
    .replace(
      /(TargetAttributes = \{\n)/,
      `$1\t\t\t\t\t${id.target} = {\n\t\t\t\t\t\tCreatedOnToolsVersion = 16.0;\n\t\t\t\t\t\tTestTargetID = ${appTarget};\n\t\t\t\t\t};\n`,
    )
    .replace(/(targets = \(\n\t\t\t\t\w{24} \/\* App \*\/,\n)/, `$1\t\t\t\t${id.target} /* AppUITests */,\n`);
  // PBXContainerItemProxy / PBXTargetDependency do not exist in the generated project.
  pbxNext = pbxNext.replace(
    "/* Begin PBXFileReference section */",
    section(
      "PBXContainerItemProxy",
      `\t\t${id.proxy} /* PBXContainerItemProxy */ = {\n\t\t\tisa = PBXContainerItemProxy;\n\t\t\tcontainerPortal = ${project} /* Project object */;\n\t\t\tproxyType = 1;\n\t\t\tremoteGlobalIDString = ${appTarget};\n\t\t\tremoteInfo = App;\n\t\t};\n`,
    ).trimStart() + "\n/* Begin PBXFileReference section */",
  );
  pbxNext = pbxNext.replace(
    "/* Begin PBXResourcesBuildPhase section */",
    section(
      "PBXTargetDependency",
      `\t\t${id.dependency} /* PBXTargetDependency */ = {\n\t\t\tisa = PBXTargetDependency;\n\t\t\ttarget = ${appTarget} /* App */;\n\t\t\ttargetProxy = ${id.proxy} /* PBXContainerItemProxy */;\n\t\t};\n`,
    ).trimStart() + "\n/* Begin PBXResourcesBuildPhase section */",
  );
  add(
    "PBXFrameworksBuildPhase",
    `\t\t${id.frameworks} /* Frameworks */ = {\n\t\t\tisa = PBXFrameworksBuildPhase;\n\t\t\tbuildActionMask = 2147483647;\n\t\t\tfiles = (\n\t\t\t);\n\t\t\trunOnlyForDeploymentPostprocessing = 0;\n\t\t};\n`,
  );
  add(
    "PBXResourcesBuildPhase",
    `\t\t${id.resources} /* Resources */ = {\n\t\t\tisa = PBXResourcesBuildPhase;\n\t\t\tbuildActionMask = 2147483647;\n\t\t\tfiles = (\n\t\t\t);\n\t\t\trunOnlyForDeploymentPostprocessing = 0;\n\t\t};\n`,
  );
  add(
    "PBXSourcesBuildPhase",
    `\t\t${id.sources} /* Sources */ = {\n\t\t\tisa = PBXSourcesBuildPhase;\n\t\t\tbuildActionMask = 2147483647;\n\t\t\tfiles = (\n\t\t\t\t${id.sourceBuild} /* AppUITests.swift in Sources */,\n\t\t\t);\n\t\t\trunOnlyForDeploymentPostprocessing = 0;\n\t\t};\n`,
  );
  add(
    "XCBuildConfiguration",
    `\t\t${id.debug} /* Debug */ = {\n\t\t\tisa = XCBuildConfiguration;\n\t\t\tbuildSettings = ${settings("")};\n\t\t\tname = Debug;\n\t\t};\n` +
      `\t\t${id.release} /* Release */ = {\n\t\t\tisa = XCBuildConfiguration;\n\t\t\tbuildSettings = ${settings("")};\n\t\t\tname = Release;\n\t\t};\n`,
  );
  add(
    "XCConfigurationList",
    `\t\t${id.list} /* Build configuration list for PBXNativeTarget "AppUITests" */ = {\n\t\t\tisa = XCConfigurationList;\n\t\t\tbuildConfigurations = (\n\t\t\t\t${id.debug} /* Debug */,\n\t\t\t\t${id.release} /* Release */,\n\t\t\t);\n\t\t\tdefaultConfigurationIsVisible = 0;\n\t\t\tdefaultConfigurationName = Release;\n\t\t};\n`,
  );
  pbxNext = pbxNext.replace("// !$*UTF8*$!\n", "// !$*UTF8*$!\n// MIKE_UI_TESTS: AppUITests target added by scripts/configure-ios.mjs\n");
  if (pbxNext === pbx) throw new Error("could not patch project.pbxproj");
  writeFileSync(pbxPath, pbxNext);
}

// The shared scheme: build App, and run AppUITests on `xcodebuild test`.
const schemeDir = `${iosApp}App.xcodeproj/xcshareddata/xcschemes/`;
const schemePath = `${schemeDir}App.xcscheme`;
if (!existsSync(schemePath)) {
  mkdirSync(schemeDir, { recursive: true });
  const ref = (guid, name, product) => `<BuildableReference BuildableIdentifier="primary" BlueprintIdentifier="${guid}" BuildableName="${product}" BlueprintName="${name}" ReferencedContainer="container:App.xcodeproj"></BuildableReference>`;
  const appGuid = /(\w{24}) \/\* App \*\/ = \{\n\t*isa = PBXNativeTarget;/.exec(readFileSync(pbxPath, "utf8"))[1];
  const appRef = ref(appGuid, "App", "App.app");
  const testRef = ref("A1B2C3D4E5F60718293A4B05", "AppUITests", "AppUITests.xctest");
  writeFileSync(
    schemePath,
    `<?xml version="1.0" encoding="UTF-8"?>
<!-- MIKE_UI_TESTS: written by scripts/configure-ios.mjs -->
<Scheme LastUpgradeVersion="0920" version="1.3">
   <BuildAction parallelizeBuildables="YES" buildImplicitDependencies="YES">
      <BuildActionEntries>
         <BuildActionEntry buildForTesting="YES" buildForRunning="YES" buildForProfiling="YES" buildForArchiving="YES" buildForAnalyzing="YES">
            ${appRef}
         </BuildActionEntry>
      </BuildActionEntries>
   </BuildAction>
   <TestAction buildConfiguration="Debug" selectedDebuggerIdentifier="Xcode.DebuggerFoundation.Debugger.LLDB" selectedLauncherIdentifier="Xcode.DebuggerFoundation.Launcher.LLDB" shouldUseLaunchSchemeArgsEnv="YES">
      <Testables>
         <TestableReference skipped="NO">
            ${testRef}
         </TestableReference>
      </Testables>
   </TestAction>
   <LaunchAction buildConfiguration="Debug" selectedDebuggerIdentifier="Xcode.DebuggerFoundation.Debugger.LLDB" selectedLauncherIdentifier="Xcode.DebuggerFoundation.Launcher.LLDB" launchStyle="0" useCustomWorkingDirectory="NO" ignoresPersistentStateOnLaunch="NO" debugDocumentVersioning="YES" debugServiceExtension="internal" allowLocationSimulation="YES">
      <BuildableProductRunnable runnableDebuggingMode="0">
         ${appRef}
      </BuildableProductRunnable>
   </LaunchAction>
   <ProfileAction buildConfiguration="Release" shouldUseLaunchSchemeArgsEnv="YES" savedToolIdentifier="" useCustomWorkingDirectory="NO" debugDocumentVersioning="YES">
      <BuildableProductRunnable runnableDebuggingMode="0">
         ${appRef}
      </BuildableProductRunnable>
   </ProfileAction>
   <AnalyzeAction buildConfiguration="Debug"></AnalyzeAction>
   <ArchiveAction buildConfiguration="Release" revealArchiveInOrganizer="YES"></ArchiveAction>
</Scheme>
`,
  );
}

console.log("ios configured");
